import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboardSections().getDashboardSection("blog", Map.of("duration", "last_7_days"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
System.out.println(body.get("section") + " " + body.get("comments_to_moderate"));
System.out.println(((Map<?, ?>) body.get("drafts_to_publish")).get("count"));
for (Object row : (List<?>) body.get("most_viewed_posts")) {
    Map<?, ?> entry = (Map<?, ?>) row;
    System.out.println(((Map<?, ?>) entry.get("post")).get("name") + " " + entry.get("views"));
}
